def state_facts(record, prefix, index):
    form = record.get('form')
    start = record.get('start_date')
    end = record.get('end_date')
    date = record.get('as_of_date')
    if form == 'onset_only':
        return None
    if form == 'active_on_date':
        if type(date) is not str:
            return []
        start = date
        end = date
    elif form == 'ongoing_since':
        if type(start) is not str:
            return []
        end = None
    elif form == 'closed_interval':
        if type(start) is not str or type(end) is not str:
            return []
    else:
        return []
    event = prefix + str(index)
    rows = [{'event': event, 'start': start, 'end': end}]
    return rows


